$offer_created=Offers::save($offer_form);$offer_assert(is_array($offer_created),'Custom offer workspace creates an audited draft');$offer_id=(int)$offer_created['id'];$offer_repeat=Offers::save($offer_form);$offer_assert(is_array($offer_repeat)&&$offer_repeat['id']===$offer_id&&!empty($offer_repeat['replayed']),'Repeated create submission reuses its offer without duplicating the post');$offer_assert(is_wp_error(Offers::save(array_replace($offer_form,array('title'=>'Conflicting duplicate')))),'A reused create request cannot silently create a different offer');
