$offer_form['post_id']=(string)$offer_id;$offer_form['revision']=Offers::fingerprint($offer_id);$offer_form['status']='publish';$offer_publish=Offers::save($offer_form);$offer_assert(is_array($offer_publish)&&\AutoDealership\Content\PublicOfferView::for_post($offer_id)!==null,'Available valid offer publishes through the existing public read model');$offer_url=get_permalink($offer_id);
$offer_assert(is_wp_error(Offers::save($offer_form)),'Outdated offer form cannot overwrite a newer save');$offer_form['revision']=Offers::fingerprint($offer_id);
$offer_assert(is_wp_error(Offers::save(array_replace($offer_form,array('new_price'=>'85000.50')))),'Offer fields reject decimal values unsupported by the public price contract');
$offer_assert(is_wp_error(Offers::save(array_replace($offer_form,array('old_price'=>'100')))),'Previous price must exceed the promotional price');
$offer_assert(is_wp_error(Offers::save(array_replace($offer_form,array('expires'=>'2026-02-30')))),'Invalid calendar expiry is rejected');
$offer_assert(is_wp_error(Offers::save(array_replace($offer_form,array('expires'=>'2020-01-01')))),'Expired offer cannot be newly published');
$offer_assert(is_wp_error(Offers::save(array_replace($offer_form,array('car_id'=>'0')))),'Published offer requires a linked available vehicle');
$offer_fault=static fn($sql)=>str_contains($sql,'INSERT INTO `'.\AutoDealership\Database\Schema::table('audit_events').'`')?'INSERT INTO `'.\AutoDealership\Database\Schema::table('audit_events').'` (missing_column) VALUES (1)':$sql;
$offer_before=Offers::fingerprint($offer_id);add_filter('query',$offer_fault);$offer_failed=Offers::save(array_replace($offer_form,array('title'=>'Must roll back')));remove_filter('query',$offer_fault);$offer_assert(is_wp_error($offer_failed)&&Offers::fingerprint($offer_id)===$offer_before,'Required audit failure rolls back offer content and metadata');
