$offer_assert(is_wp_error(Offers::change_status($offer_id,'trash',$offer_before)),'Repeated stale trash request cannot delete an offer');
$offer_restore=static fn()=> 'publish';add_filter('wp_untrash_post_status',$offer_restore);$offer_restored=Offers::change_status($offer_id,'restore',Offers::fingerprint($offer_id));remove_filter('wp_untrash_post_status',$offer_restore);$offer_assert(is_array($offer_restored)&&get_post_status($offer_id)==='draft','Restored offer stays a draft even if a plugin requests republishing');
$offer_form['revision']=Offers::fingerprint($offer_id);$offer_republished=Offers::save($offer_form);$offer_assert(is_array($offer_republished)&&get_permalink($offer_id)===$offer_url,'Republishing the restored offer preserves its original public URL');
