$_GET=array('page'=>'adc-offer-publishing');ob_start();OfferPage::render();$offer_list=ob_get_clean();$offer_assert(str_contains($offer_list,'adc_offer_status')&&str_contains($offer_list,'name="search"'),'Custom offer list provides search and protected publication actions');
